#!/usr/bin/env python3
"""
Generate the remaining Jōyō Kanji entries to reach 2,136.
Uses a compact data format and merges with existing data.
"""
import json

# Load existing
with open("data/kanji.json", "r", encoding="utf-8") as f:
    data = json.load(f)

print(f"Starting with {len(data)} kanji")

def add(k, on, kun, m, c):
    if k not in data:
        data[k] = {"on": on, "kun": kun, "m": m, "c": c}

